export const LANGUAGE_KEY='cubemine-language-v1';
let language='es';
export const normalizeLanguage=value=>value==='en'?'en':'es';
export function initializeLanguage(storage){
  try{language=normalizeLanguage((storage??globalThis.localStorage)?.getItem(LANGUAGE_KEY));}catch{language='es';}
  return language;
}
export const getLanguage=()=>language;
export function setLanguage(value,storage){
  language=normalizeLanguage(value);
  try{(storage??globalThis.localStorage)?.setItem(LANGUAGE_KEY,language);}catch{}
  return language;
}
export function t(key,values={},locale=language){
  const text=MESSAGES[normalizeLanguage(locale)][key];
  if(text===undefined)throw new Error(`Missing translation: ${key}`);
  return text.replace(/\{(\w+)\}/g,(match,name)=>Object.hasOwn(values,name)?String(values[name]):match);
}
export const faceName=(key,locale=language)=>t('face.'+key,{},locale);
export const quantity=(count,noun,locale=language)=>t(noun+(count===1?'One':'Many'),{count},locale);
export const faceLetter=(key,locale=language)=>t('letter.'+key,{},locale);
export function cellName(game,id,locale=language){const c=game.cells[id];return t('cellName',{face:faceName(c.face,locale),row:c.row+1,col:c.col+1},locale);}
export function lineName(line,locale=language){return t('lineName',{face:faceName(line.face,locale),axis:t(line.axis,{},locale),index:line.index+1},locale);}
export const puzzleTitle=spec=>t('puzzle.'+spec.id+'.title');
export const puzzleBrief=spec=>t('puzzle.'+spec.id+'.brief');
export function translatePage(doc){
  doc.documentElement.lang=language;doc.title=t('pageTitle');
  doc.querySelector('meta[name="description"]').setAttribute('content',t('description'));
  for(const node of doc.querySelectorAll('[data-i18n-html]'))node.innerHTML=t(node.dataset.i18nHtml);
  for(const node of doc.querySelectorAll('[data-i18n-attr]'))for(const entry of node.dataset.i18nAttr.split(' ')){const [name,key]=entry.split(':');node.setAttribute(name,t(key));}
  doc.getElementById('language').value=language;
}
initializeLanguage();
